public class Warm {
    static long sink;
    static final Map<String,Integer> m = new HashMap<>();
    static int work(int x) {                       // 접기 어려운 일
        String k = "k" + (x & 1023);
        Integer v = m.get(k);
        if (v == null) { m.put(k, x); return x; }
        return v ^ x;
    }
    public static void main(String[] a) {
        int batches = 16, per = 300_000;
        for (int b = 1; b <= batches; b++) {
            long t0 = System.nanoTime(), s = 0;
            for (int i = 0; i < per; i++) s += work(i);
            sink = s;
            System.out.printf("  %2d회차  %,6d us%n", b, (System.nanoTime()-t0)/1000);
        }
    }
}

